/* منصة فيزياء ثاني ثانوي — ملف السكربت */
const chapters=[
{n:1,title:"الجاذبية",lessons:["1-1 حركة الكواكب والجاذبية","1-2 استخدام قانون الجذب الكوني"],idea:"تفسّر الجاذبية حركة الكواكب والأقمار، وتؤثر قوة التجاذب بين جسمين في كتلتيهما والمسافة بين مركزيهما.",sections:[["حركة الكواكب والجاذبية","تتحرك الكواكب في مدارات حول الشمس بفعل الجاذبية. وصف كبلر حركة الكواكب بقوانين؛ ومن أهم الأفكار أن المدار غالبًا إهليلجي، وأن الكوكب يكون أسرع عندما يكون أقرب إلى الشمس وأبطأ عندما يبتعد عنها."],["قانون الجذب الكوني","كل جسمين ماديين يتجاذبان بقوة تتناسب طرديًا مع حاصل ضرب كتلتيهما وعكسيًا مع مربع المسافة بين مركزيهما. القوة متساوية مقدارًا ومتعاكسة اتجاهًا على الجسمين."]],formula:"F = G (m₁ m₂) / r²",symbols:"F القوة (N)، G ثابت الجذب الكوني، m الكتلة (kg)، r المسافة بين مركزي الجسمين (m).",example:"إذا تضاعفت المسافة بين جسمين وبقيت الكتلتان ثابتتين، تصبح قوة الجاذبية ربع قيمتها؛ لأن القوة تتناسب عكسيًا مع مربع المسافة."},
{n:2,title:"الحركة الدورانية",lessons:["2-1 وصف الحركة الدورانية","2-2 ديناميكا الحركة الدورانية","2-3 الاتزان"],idea:"تصف الحركة الدورانية دوران الجسم حول محور، وتشرح عزم القوة كيف يمكن للقوة أن تغيّر هذا الدوران.",sections:[["وصف الحركة الدورانية","الإزاحة الزاوية تقيس مقدار الدوران، وتقاس بالراديان. السرعة الزاوية هي معدل تغير الإزاحة الزاوية، والتسارع الزاوي هو معدل تغير السرعة الزاوية."],["ديناميكا الحركة الدورانية","يعتمد عزم القوة على مقدار القوة والمسافة العمودية عن محور الدوران. تزداد فاعلية القوة عندما تؤثر بعيدًا عن المحور وباتجاه عمودي."],["الاتزان","يتزن الجسم اتزانًا انتقاليًا عندما تكون محصلة القوى صفرًا، واتزانًا دورانيًا عندما تكون محصلة عزوم القوى صفرًا."]],formula:"τ = r F sin(θ)   |   Στ = 0",symbols:"τ عزم القوة (N·m)، r ذراع القوة (m)، F القوة (N)، θ الزاوية بين متجه الموضع والقوة.",example:"فتح الباب أسهل عند دفعه من المقبض بعيدًا عن المفصلات؛ لأن ذراع القوة أكبر فينتج عزم أكبر للقوة نفسها."},
{n:3,title:"الزخم وحفظه",lessons:["3-1 الدفع والزخم","3-2 حفظ الزخم"],idea:"يربط الزخم بين كتلة الجسم وسرعته، ويعبّر الدفع عن أثر القوة خلال زمن محدد.",sections:[["الدفع والزخم","الزخم كمية متجهة تساوي حاصل ضرب الكتلة في السرعة. الدفع يساوي القوة المحصلة مضروبة في زمن تأثيرها، ويساوي التغير في الزخم."],["حفظ الزخم","في نظام معزول لا تؤثر فيه محصلة قوى خارجية، يبقى الزخم الكلي قبل التفاعل مساويًا للزخم الكلي بعده."]],formula:"p = m v   |   J = FΔt = Δp",symbols:"p الزخم (kg·m/s)، m الكتلة (kg)، v السرعة (m/s)، J الدفع (N·s).",example:"عند تصادم جسمين، اكتب مجموع زخم الجسمين قبل التصادم ومجموعهما بعده، ثم ساوِ الطرفين مع مراعاة الإشارات والاتجاهات."},
{n:4,title:"الشغل والطاقة والآلات البسيطة",lessons:["4-1 الطاقة والشغل","4-2 الآلات"],idea:"يحدث الشغل عندما تؤثر قوة في جسم وتسبب إزاحة لها مركبة في اتجاه القوة. وتساعد الآلات على تغيير مقدار القوة أو اتجاهها.",sections:[["الطاقة والشغل","الشغل هو انتقال للطاقة بفعل قوة خلال إزاحة. عندما تكون القوة في اتجاه الإزاحة يكون الشغل موجبًا، وعكس اتجاهها يكون سالبًا، وعند التعامد يكون الشغل صفرًا."],["الآلات","الفائدة الميكانيكية تقارن القوة الناتجة بالقوة المبذولة. الآلات المثالية لا تفقد طاقة، بينما تقل الفائدة الفعلية بسبب الاحتكاك وفقد الطاقة الحرارية."]],formula:"W = F d cos(θ)   |   P = W / t",symbols:"W الشغل (J)، F القوة (N)، d الإزاحة (m)، θ الزاوية، P القدرة (W)، t الزمن (s).",example:"قوة مقدارها 10 N تحرك جسمًا 3 m في اتجاهها: الشغل = 10 × 3 = 30 J."},
{n:5,title:"الطاقة وحفظها",lessons:["5-1 الأشكال المتعددة للطاقة","5-2 حفظ الطاقة"],idea:"توجد الطاقة بأشكال متعددة، ويمكن أن تتحول من شكل إلى آخر. في نظام معزول تبقى الطاقة الكلية محفوظة.",sections:[["الأشكال المتعددة للطاقة","من أشكال الطاقة: الحركية، وطاقة الوضع الجاذبية، والطاقة المرونية، والحرارية والكيميائية. اختيار النموذج المناسب يعتمد على النظام المدروس."],["حفظ الطاقة","يمكن أن تتحول طاقة الوضع إلى طاقة حركية مثل سقوط جسم. عند إهمال مقاومة الهواء، يظل مجموع طاقتي الحركة والوضع ثابتًا في هذا المثال."]],formula:"K = ½mv²   |   Ug = mgh",symbols:"K الطاقة الحركية (J)، m الكتلة (kg)، v السرعة (m/s)، Ug طاقة وضع الجاذبية (J)، g تسارع الجاذبية (m/s²)، h الارتفاع (m).",example:"جسم كتلته 2 kg على ارتفاع 5 m، بافتراض g = 9.8 m/s²: طاقة وضعه = 2 × 9.8 × 5 = 98 J."},
{n:6,title:"الطاقة الحرارية",lessons:["6-1 درجة الحرارة والطاقة الحرارية","6-2 تغيرات حالة المادة وقوانين الديناميكا الحرارية"],idea:"ترتبط درجة الحرارة بمتوسط الطاقة الحركية للجسيمات، بينما تعتمد الطاقة الحرارية على حركة الجسيمات وتفاعلاتها وعددها.",sections:[["درجة الحرارة والطاقة الحرارية","درجة الحرارة مقياس يرتبط بمتوسط الطاقة الحركية للجسيمات. تنتقل الطاقة الحرارية تلقائيًا من الجسم الأعلى درجة حرارة إلى الجسم الأقل حتى الوصول إلى الاتزان الحراري."],["تغيرات الحالة والديناميكا الحرارية","تحتاج المادة إلى امتصاص أو إطلاق طاقة لتغيير حالتها. أثناء تغير الحالة لمادة نقية عند ضغط ثابت تبقى درجة الحرارة ثابتة عادةً رغم استمرار انتقال الطاقة. القانون الأول للديناميكا الحرارية يربط تغير الطاقة الداخلية بالحرارة والشغل وفق اصطلاح الإشارة المستخدم."]],formula:"Q = m c ΔT   |   Q = m L",symbols:"Q الحرارة المنتقلة (J)، m الكتلة (kg)، c الحرارة النوعية (J/kg·°C)، ΔT التغير في درجة الحرارة، L الحرارة الكامنة النوعية (J/kg).",example:"تسخين 0.5 kg من الماء بمقدار 10°C، باستخدام c = 4180 J/(kg·°C): Q = 0.5 × 4180 × 10 = 20,900 J."}
];
