function renderChapters(filter=""){
 const list=document.getElementById('chapterList');list.innerHTML="";
 const filtered=chapters.filter(c=>(c.title+" "+c.lessons.join(" ")).toLowerCase().includes(filter.toLowerCase()));
 if(!filtered.length){list.innerHTML='<div class="info">ما لقينا فصل أو درس بهذا الاسم. جرّب كلمة ثانية.</div>';return;}
 filtered.forEach(c=>{const b=document.createElement('button');b.className='lesson-link';b.innerHTML=`<strong><span style="color:var(--champagne)">الفصل ${c.n.toLocaleString('ar-SA')}</span> · ${c.title}</strong><small>${c.idea}</small><div class="chapter-card-meta"><span class="chapter-chip">${c.lessons.length.toLocaleString('ar-SA')} دروس</span><span class="chapter-chip">شرح وملخص</span><span class="chapter-chip">قوانين وتطبيق</span></div>`;b.onclick=()=>renderLesson(c.n);list.appendChild(b)});
}
function filterChapters(){renderChapters(document.getElementById('search').value.trim())}
function renderLesson(n){
 const c=chapters.find(x=>x.n===n),d=document.getElementById('lessonDetail');if(!c||!d)return;
 d.classList.remove('hide');document.getElementById('chapterList').classList.add('hide');document.getElementById('search').classList.add('hide');
 const notes=lessonNotes[n]||[];
 d.innerHTML=`<button class="btn" onclick="backToChapters()">← العودة للفصول</button><div class="lesson-hero"><span class="lesson-kicker">PHYSICS LAB · الفصل ${c.n.toLocaleString('ar-SA')}</span><h2>${c.title}</h2><p class="muted">${c.idea}</p><div class="chapter-card-meta"><span class="chapter-chip">${c.lessons.length.toLocaleString('ar-SA')} دروس</span><span class="chapter-chip">ملخصات مركزة</span><span class="chapter-chip">تطبيق عملي</span></div></div><h3>اختر الدرس الذي تريد دراسته</h3><div class="lesson-picker">${c.lessons.map((name,i)=>`<button class="lesson-choice" onclick="renderSingleLesson(${n},${i})"><b>${name}</b><small>${(notes[i]&&notes[i].summary)||((c.sections[i]&&c.sections[i][1])||'شرح الفكرة الأساسية للدرس.')}</small><span class="chapter-chip">افتح الدرس ←</span></button>`).join('')}</div><div class="info"><strong>قانون الفصل:</strong><div class="formula">${c.formula}</div><p class="muted">${c.symbols}</p></div>`;
 d.scrollIntoView({behavior:'smooth',block:'start'});
}
function backToChapters(){const d=document.getElementById('lessonDetail');d.classList.add('hide');d.innerHTML='';document.getElementById('chapterList').classList.remove('hide');document.getElementById('search').classList.remove('hide');}
function renderSingleLesson(n,i){
 const c=chapters.find(x=>x.n===n),d=document.getElementById('lessonDetail');if(!c)return;
 const l=(lessonNotes[n]||[])[i]||{},sec=c.sections[i]||[],title=l.title||sec[0]||c.lessons[i],summary=l.summary||sec[1]||c.idea,goals=l.goals||['فهم الفكرة الأساسية للدرس.','تحديد القانون المناسب وتفسير رموزه.','تطبيق المفهوم على مثال واقعي.'],terms=l.terms||c.symbols,check=l.check||'اكتب المعطيات أولًا، ثم اختر القانون المناسب وتحقق من الوحدات.';
 const prev=i>0?`<button class="btn" onclick="renderSingleLesson(${n},${i-1})">→ الدرس السابق</button>`:`<button class="btn" onclick="renderLesson(${n})">فهرس الفصل</button>`;
 const next=i<c.lessons.length-1?`<button class="btn primary" onclick="renderSingleLesson(${n},${i+1})">الدرس التالي ←</button>`:`<button class="btn primary" onclick="showSection('quiz')">اختبر فهمك ←</button>`;
 d.innerHTML=`<button class="btn" onclick="renderLesson(${n})">← فهرس الفصل</button><div class="lesson-hero"><span class="lesson-kicker">LESSON ${n}.${i+1} · PHYSICS 02</span><h2>${title}</h2><p class="muted">${c.title} — ${i+1} من ${c.lessons.length} دروس</p></div><h3>ماذا ستتعلم؟</h3><div class="grid2">${goals.map((g,j)=>`<div class="mini"><h4>المحور ${['الأول','الثاني','الثالث'][j]||j+1}</h4><p>${g}</p></div>`).join('')}</div><h3>شرح الدرس</h3><div class="question"><p>${summary}</p></div><div class="info"><strong>مصطلحات وملاحظات:</strong><p>${terms}</p></div><div class="info"><strong>قاعدة ذهبية:</strong><p>${check}</p></div><h3>قانون مهم</h3><div class="formula">${c.formula}</div><p class="muted">${c.symbols}</p><h3>تطبيق وفهم</h3><div class="mini"><h4>مثال توضيحي</h4><p>${c.example}</p><p class="muted">في الحلول العددية: اكتب المعطيات، وحّد الوحدات، عوّض في القانون، ثم اكتب النتيجة بوحدتها.</p></div><div class="lesson-nav">${prev}${next}</div>`;
 d.scrollIntoView({behavior:'smooth',block:'start'});
}
function renderLaws(){document.getElementById('lawsList').innerHTML=laws.map(x=>`<div class="mini" style="margin:10px 0"><h4>${x[0]}</h4><div class="formula">${x[1]}</div><p class="muted">${x[2]}</p></div>`).join("")}
function renderSolved(){document.getElementById('solvedList').innerHTML=solved.map((x,i)=>`<div class="question"><h3 style="margin-top:0">${x[0]}</h3><p>${x[1]}</p><button class="btn" onclick="document.getElementById('solution${i}').classList.toggle('hide')">عرض الحل</button><div id="solution${i}" class="hide"><div class="formula">${x[2]}</div><p class="muted">${x[3]}</p></div></div>`).join("")}
let score=0,answered=new Set();
function renderQuiz(){document.getElementById('quizList').innerHTML=questions.map((q,i)=>`<div class="question" id="q${i}"><p>${i+1}. ${q.q}</p>${q.o.map((o,j)=>`<button class="option" onclick="answer(${i},${j},this)">${["أ","ب","ج","د"][j]}) ${o}</button>`).join("")}<div class="feedback" id="f${i}"></div></div>`).join("")}
function answer(i,j,el){if(answered.has(i))return;answered.add(i);updateQuizProgress();const q=questions[i],parent=document.getElementById('q'+i);parent.querySelectorAll('.option').forEach((b,k)=>{b.disabled=true;if(k===q.a)b.classList.add('correct')});if(j===q.a){score++;document.getElementById('f'+i).textContent="إجابة صحيحة! "+q.e}else{el.classList.add('wrong');document.getElementById('f'+i).textContent="ليست الإجابة الصحيحة. "+q.e}document.getElementById('scoreStat').textContent=score.toLocaleString('ar-SA');}
function resetQuiz(){score=0;answered=new Set();document.getElementById('scoreStat').textContent="٠";renderQuiz();updateQuizProgress()}
function updateQuizProgress(){const count=answered.size;document.getElementById('quizProgressText').textContent=`أكملت ${count} من ${questions.length} أسئلة`;document.getElementById('quizProgressBar').style.width=(count/questions.length*100)+'%'}
window.addEventListener('scroll',()=>{const max=document.documentElement.scrollHeight-window.innerHeight;document.getElementById('readingProgress').style.width=(max>0?window.scrollY/max*100:0)+'%'},{passive:true});
function showSection(id){document.querySelectorAll('.section').forEach(s=>s.classList.add('hide'));document.getElementById(id).classList.remove('hide');document.querySelectorAll('.navbtn').forEach(b=>b.classList.toggle('active',b.dataset.section===id));if(id!=='chapters'){document.getElementById('lessonDetail').classList.add('hide')}else{backToChapters()}document.querySelector('.content-card').scrollIntoView({behavior:'smooth',block:'start'})}
renderChapters();renderLaws();renderSolved();renderQuiz();

