// ===== مقاطع شرح متحركة =====
const XC=['#8ff4ff','#f1d39b','#a895ff','#6df5bd','#ff8585'];
const arr=(g,x,y,X,Y,c,w=3)=>{const a=Math.atan2(Y-y,X-x);g.strokeStyle=g.fillStyle=c;g.lineWidth=w;g.beginPath();g.moveTo(x,y);g.lineTo(X,Y);g.stroke();g.beginPath();g.moveTo(X,Y);g.lineTo(X-11*Math.cos(a-.4),Y-11*Math.sin(a-.4));g.lineTo(X-11*Math.cos(a+.4),Y-11*Math.sin(a+.4));g.fill()};
const txt=(g,s,x,y,c='#cfe0ff',al='center')=>{g.fillStyle=c;g.textAlign=al;g.font='bold 14px Tahoma,Arial';g.fillText(s,x,y)};
const dot=(g,x,y,r,c)=>{g.fillStyle=c;g.beginPath();g.arc(x,y,r,0,7);g.fill()};
const dash=(g,x,y,X,Y,c)=>{g.strokeStyle=c;g.lineWidth=2;g.setLineDash([5,5]);g.beginPath();g.moveTo(x,y);g.lineTo(X,Y);g.stroke();g.setLineDash([])};
const CL=[
{t:"الجذب الكوني",f:"F = G m₁m₂/r²",s:["كل جسمين يتجاذبان بقوتين متساويتين في المقدار ومتعاكستين في الاتجاه.","حرّك m₁ أو m₂: القوة تتناسب طرديًا مع حاصل ضرب الكتلتين.","غيّر المسافة r: عند مضاعفتها تصبح القوة ربع قيمتها."],
c:[['a','الكتلة m₁',1,5,2,1],['b','الكتلة m₂',1,5,3,1],['r','المسافة r',1,4,2,.5]],
d(g,t,p){const r=p.r,F=p.a*p.b/r/r,A=300-r*55-20,B=300+r*55+20,ra=10+p.a*4,rb=10+p.b*4,gap=(B-A-ra-rb-16)/2,L=Math.max(6,Math.min(gap,16*Math.sqrt(F)*(1+.05*Math.sin(t*4))));
dot(g,A,140,ra,XC[0]);dot(g,B,140,rb,XC[1]);arr(g,A+ra+4,140,A+ra+4+L,140,XC[3]);arr(g,B-rb-4,140,B-rb-4-L,140,XC[3]);dash(g,A,210,B,210,'#5a6b90');txt(g,'r',300,232,'#9fb0d0');txt(g,'m₁',A,70,XC[0]);txt(g,'m₂',B,70,XC[1]);return 'F ∝ m₁m₂/r² = '+F.toFixed(2)+' (وحدات نسبية)'}},
{t:"قوانين كبلر",f:"T² ∝ r³",s:["الكوكب يدور في مدار إهليلجي والشمس في إحدى بؤرتيه.","المنطقة المظللة تُمسح في أزمنة متساوية.","راقب قراءة السرعة: أكبر ما تكون عند الأقرب وأقل ما تكون عند الأبعد."],
c:[['s','سرعة العرض',.5,3,1.2,.1]],
d(g,t,p){const a=230,b=130,c=Math.sqrt(a*a-b*b),e=c/a,cx=300,cy=165,M=t*p.s,E=m=>{let x=m;for(let i=0;i<9;i++)x=m+e*Math.sin(x);return x},P=m=>{const x=E(m);return[cx+a*Math.cos(x),cy+b*Math.sin(x)]};
g.strokeStyle='#33466b';g.lineWidth=2;g.beginPath();g.ellipse(cx,cy,a,b,0,0,7);g.stroke();const sx=cx+c;g.fillStyle='#8ff4ff33';g.beginPath();g.moveTo(sx,cy);for(let i=0;i<=12;i++){const q=P(M-.9+.9*i/12);g.lineTo(q[0],q[1])}g.fill();dot(g,sx,cy,13,XC[1]);const q=P(M);dot(g,q[0],q[1],8,XC[0]);const r=Math.hypot(q[0]-sx,q[1]-cy)/a;return 'البعد = '+r.toFixed(2)+' a ، السرعة النسبية = '+Math.sqrt(2/r-1).toFixed(2)}},
{t:"الحركة الدائرية",f:"v = rω ، aᶜ = rω²",s:["نقطة تدور على دائرة بسرعة زاوية ω ونصف قطر r.","السهم الأصفر هو السرعة الخطية v = rω ويكون مماسًا للمسار دائمًا.","السهم الأحمر هو التسارع المركزي ويتجه نحو المركز؛ زد ω وشاهده يزداد بالتربيع."],
c:[['r','نصف القطر r (m)',.5,3,2,.5],['w','السرعة الزاوية ω',.5,4,1.5,.5]],
d(g,t,p){const cx=320,cy=160,R=p.r*50,th=p.w*t,x=cx+R*Math.cos(th),y=cy-R*Math.sin(th),v=p.r*p.w,ac=p.r*p.w*p.w;g.strokeStyle='#33466b';g.lineWidth=2;g.beginPath();g.arc(cx,cy,R,0,7);g.stroke();dot(g,cx,cy,4,'#5a6b90');dash(g,cx,cy,x,y,'#5a6b90');dot(g,x,y,10,XC[0]);const vl=Math.min(110,v*22),al=Math.min(100,ac*7);arr(g,x,y,x-vl*Math.sin(th),y-vl*Math.cos(th),XC[1]);arr(g,x,y,x-al*Math.cos(th),y+al*Math.sin(th),XC[4]);return 'v = rω = '+v.toFixed(2)+' m/s ، aᶜ = rω² = '+ac.toFixed(2)+' m/s²'}},
{t:"عزم القوة",f:"τ = rF sinθ",s:["العزم يقيس قدرة القوة على تدوير الجسم حول المحور.","كبّر الذراع r: يزداد العزم للقوة نفسها.","غيّر الزاوية θ: المؤثر هو المركبة العمودية F sinθ، وعند θ = 0 ينعدم العزم."],
c:[['r','الذراع r (m)',.2,.9,.6,.1],['F','القوة F (N)',5,30,20,1],['th','الزاوية θ (°)',0,90,90,5]],
d(g,t,p){const px=110,py=170,L=p.r*320,th=p.th*Math.PI/180,ex=px+L,F=p.F*3.2;dot(g,px,py,10,'#5a6b90');g.strokeStyle=XC[2];g.lineWidth=12;g.lineCap='round';g.beginPath();g.moveTo(px,py);g.lineTo(ex,py);g.stroke();g.lineCap='butt';arr(g,ex,py,ex+F*Math.cos(th),py-F*Math.sin(th),XC[3]);dash(g,ex,py,ex,py-F*Math.sin(th),'#f1d39b');txt(g,'r',px+L/2,py+40,XC[1]);return 'τ = rF sinθ = '+(p.r*p.F*Math.sin(th)).toFixed(2)+' N·m'}},
{t:"حفظ الزخم",f:"m₁v₁ = (m₁+m₂)v′",s:["عربة متحركة تصطدم بعربة ساكنة وتلتحمان (تصادم غير مرن تمامًا).","الزخم الكلي قبل التصادم يساوي الزخم الكلي بعده.","زد كتلة العربة الثانية وشاهد السرعة النهائية تقل."],
c:[['m1','كتلة العربة 1',1,5,3,1],['v','سرعتها v₁',1,6,4,1],['m2','كتلة العربة 2',1,5,2,1]],
d(g,t,p){const w1=36+p.m1*8,w2=36+p.m2*8,s=25,x2=340,tc=2,u=t%3.8,vf=p.m1*p.v/(p.m1+p.m2),x1=u<tc?x2-w1-p.v*s*(tc-u):x2-w1+vf*s*(u-tc),xx=u<tc?x2:x2+vf*s*(u-tc);g.fillStyle='#33466b';g.fillRect(20,262,600,4);g.fillStyle=XC[0];g.fillRect(x1,222,w1,40);g.fillStyle=XC[1];g.fillRect(xx,222,w2,40);txt(g,p.m1+' kg',x1+w1/2,246,'#06121d');txt(g,p.m2+' kg',xx+w2/2,246,'#06121d');if(u<tc)arr(g,x1+w1/2,200,x1+w1/2+p.v*14,200,XC[3]);else arr(g,x1+w1/2,200,x1+w1/2+vf*14,200,XC[3]);return 'p قبل = '+p.m1*p.v+' kg·m/s ، v′ = '+vf.toFixed(2)+' m/s ، p بعد = '+((p.m1+p.m2)*vf).toFixed(1)}},
{t:"الشغل",f:"W = Fd cosθ",s:["الشغل يحتاج قوة وإزاحة، والمؤثر منها هو المركبة في اتجاه الحركة.","الخط المنقط F cosθ هو ما يُنجز الشغل فعلًا.","اجعل θ = 90° فيصبح الشغل صفرًا مهما كبرت القوة."],
c:[['F','القوة F (N)',10,40,25,5],['th','الزاوية θ (°)',0,90,30,5],['d','الإزاحة d (m)',1,8,6,1]],
d(g,t,p){const th=p.th*Math.PI/180,u=Math.min(1,(t%4)/3),x=70+u*p.d*50,cx=x+35,cy=225,F=p.F*2.4;g.fillStyle='#33466b';g.fillRect(30,250,580,4);g.fillStyle=XC[2];g.fillRect(x,200,70,50);arr(g,cx,cy,cx+F*Math.cos(th),cy-F*Math.sin(th),XC[3]);dash(g,cx,cy,cx+F*Math.cos(th),cy,'#f1d39b');arr(g,105,285,105+p.d*50,285,XC[1],2);txt(g,'d',105+p.d*25,306,XC[1]);return 'W = Fd cosθ = '+(p.F*p.d*Math.cos(th)).toFixed(1)+' J'}},
{t:"حفظ الطاقة",f:"K + Ug = ثابت",s:["عند أعلى نقطة تكون كل الطاقة طاقة وضع Ug.","أثناء السقوط تنقص Ug وتزداد K بالمقدار نفسه.","المجموع (الخط الأحمر) ثابت لأن مقاومة الهواء مهملة."],
c:[['m','الكتلة m (kg)',1,5,2,1],['h','الارتفاع h (m)',1,5,4,1]],
d(g,t,p){const m=p.m,h0=p.h,k0=.45,tf=Math.sqrt(2*h0/9.8)/k0,u=t%(tf+1),te=Math.min(u,tf)*k0,h=Math.max(0,h0-4.9*te*te),K=m*9.8*(h0-h),U=m*9.8*h,E=m*9.8*h0,sc=190/E;g.fillStyle='#33466b';g.fillRect(430,250,180,4);dot(g,520,238-h*44,12,XC[1]);g.fillStyle=XC[1];g.fillRect(90,250-U*sc,60,U*sc);g.fillStyle=XC[0];g.fillRect(190,250-K*sc,60,K*sc);dash(g,70,250-E*sc,280,250-E*sc,XC[4]);txt(g,'Ug',120,272,XC[1]);txt(g,'K',220,272,XC[0]);txt(g,'K+Ug',290,254-E*sc,XC[4],'left');return 'K = '+K.toFixed(0)+' J ، Ug = '+U.toFixed(0)+' J ، المجموع = '+E.toFixed(0)+' J'}},
{t:"الحرارة وتغير الحالة",f:"Q = mcΔT ، Q = mL",s:["تسخين الجليد يرفع درجة حرارته وفق Q = mcΔT.","عند 0°C ينصهر الجليد والحرارة ثابتة؛ الطاقة تُستهلك في تغيير الحالة Q = mL.","يسخن الماء حتى 100°C ثم يغلي بدرجة ثابتة، ثم يسخن البخار."],
c:[],
d(g,t){const S=[[-20,0,60,'جليد'],[0,0,70,'انصهار'],[0,100,160,'ماء'],[100,100,200,'غليان'],[100,140,60,'بخار']],X0=60,Y=T=>262-(T+20)*1.5;let x=X0;const path=[[x,Y(-20)]],seg=[];S.forEach(s=>{seg.push([x,x+s[2]]);x+=s[2];path.push([x,Y(s[1])])});g.strokeStyle='#5a6b90';g.lineWidth=2;g.beginPath();g.moveTo(X0,16);g.lineTo(X0,262);g.lineTo(620,262);g.stroke();g.strokeStyle=XC[0];g.lineWidth=3;g.beginPath();path.forEach((q,i)=>i?g.lineTo(q[0],q[1]):g.moveTo(q[0],q[1]));g.stroke();S.forEach((s,i)=>txt(g,s[3],(path[i][0]+path[i+1][0])/2,Math.min(path[i][1],path[i+1][1])-10,i%2?XC[4]:XC[1]));const px=X0+Math.min(1,(t*.1)%1.15)*550;let i=seg.findIndex(q=>px<=q[1]);if(i<0)i=4;const s=S[i],T=s[0]+(s[1]-s[0])*(px-seg[i][0])/s[2];dot(g,px,Y(T),9,XC[3]);return s[3]+' — T = '+T.toFixed(0)+'°C — '+(i%2?'Q = mL (الحرارة ثابتة)':'Q = mcΔT')}}
];
let ci=0,si=0,pz=false,tt=0,lt=0,run=false;const xcv=document.getElementById('xc');
function xLoad(i){ci=i;si=0;tt=0;window.speechSynthesis&&speechSynthesis.cancel();const c=CL[i];
document.getElementById('xChips').innerHTML=CL.map((q,j)=>`<button class="chip ${j===i?'on':''}" onclick="xLoad(${j})">${q.t}</button>`).join('');
document.getElementById('xCtl').innerHTML=c.c.map(k=>`<label>${k[1]}: <b id="xv_${k[0]}">${k[4]}</b><input type="range" id="xc_${k[0]}" min="${k[2]}" max="${k[3]}" step="${k[5]}" value="${k[4]}"></label>`).join('');
document.getElementById('xFormula').textContent=c.f;xCap()}
function xCap(){const c=CL[ci];document.getElementById('xCap').textContent=`الخطوة ${(si+1).toLocaleString('ar-SA')} من ${c.s.length.toLocaleString('ar-SA')}: ${c.s[si]}`}
function xStep(d){const n=CL[ci].s.length;si=(si+d+n)%n;xCap()}
function xPause(b){pz=!pz;b.textContent=pz?'تشغيل':'إيقاف'}
function xSpeak(){if(!window.speechSynthesis)return;const u=new SpeechSynthesisUtterance(CL[ci].s[si]);u.lang='ar-SA';speechSynthesis.cancel();speechSynthesis.speak(u)}
function xFrame(){const c=CL[ci],p={};c.c.forEach(k=>{const e=document.getElementById('xc_'+k[0]);p[k[0]]=+e.value;document.getElementById('xv_'+k[0]).textContent=e.value});const g=xcv.getContext('2d');g.clearRect(0,0,640,320);g.lineWidth=2;g.setLineDash([]);document.getElementById('xRead').textContent=c.d(g,tt,p)}
function xLoop(ts){if(!run)return;const dt=Math.min(.05,(ts-lt)/1000||0);lt=ts;if(!pz)tt+=dt;xFrame();requestAnimationFrame(xLoop)}
const _ss=showSection;showSection=function(id){_ss(id);if(id==='xplain'){if(!run){run=true;lt=performance.now();requestAnimationFrame(xLoop)}}else{run=false;window.speechSynthesis&&speechSynthesis.cancel()}};
xLoad(0);

