/* مرفوعة من هذا القسم لتحافظ على ترتيب التنفيذ الأصلي */
renderQuiz=function renderQuiz(){document.getElementById('quizList').innerHTML=questions.map((q,i)=>`<div class="question" id="q${i}"><p>${i+1}. ${q.q}</p>${q.o.map((o,j)=>`<button class="option" onclick="answer(${i},${j},this)">${["أ","ب","ج","د"][j]}) ${o}</button>`).join("")}<button class="btn lawbtn" onclick="showLaw(${i})">💡 اعرض القانون</button><div class="lawbox info hide" id="lw${i}"></div><div class="feedback" id="f${i}"></div></div>`).join("")};
answer=function answer(i,j,el){if(answered.has(i))return;answered.add(i);const q=questions[i],p=document.getElementById('q'+i);p.querySelectorAll('.option').forEach((b,k)=>{b.disabled=true;if(k===q.a)b.classList.add('correct')});if(j===q.a){score++;document.getElementById('f'+i).textContent="إجابة صحيحة! "+q.e}else{el.classList.add('wrong');document.getElementById('f'+i).textContent="ليست الإجابة الصحيحة. "+q.e}const b=document.getElementById('lw'+i);b.innerHTML=lawBox(i);b.classList.remove('hide');document.getElementById('scoreStat').textContent=score.toLocaleString('ar-SA');updateQuizProgress()};
// ===== القانون داخل الأسئلة =====
const LW=[
["قانون الجذب الكوني","F = G m₁m₂ / r²","القوة تتناسب طرديًا مع حاصل ضرب الكتلتين وعكسيًا مع مربع المسافة بين المركزين. إذا ضاعفت r تصبح القوة ربعًا، وإذا ضاعفت كتلة تتضاعف القوة."],
["قانون كبلر الثاني","المساحة الممسوحة ÷ الزمن = ثابت","الخط الواصل بين الكوكب والشمس يمسح مساحات متساوية في أزمنة متساوية، فيسرع الكوكب عند الاقتراب من الشمس."],
["قانون كبلر الثالث","T² ∝ r³","كلما كبر نصف قطر المدار زاد الزمن الدوري للكوكب."],
["السرعة الزاوية","ω = Δθ / Δt","الزاوية بالراديان والزمن بالثانية. تذكّر أن 180° = π rad و360° = 2π rad."],
["السرعة الخطية والزاوية","v = rω","السرعة الخطية لنقطة على مسار دائري تساوي نصف القطر مضروبًا في السرعة الزاوية."],
["عزم القوة","τ = r F sinθ","العزم حاصل ضرب الذراع في القوة في جيب الزاوية بينهما، ويكون أكبر ما يمكن عند 90°."],
["شرطا الاتزان","ΣF = 0 ، Στ = 0","الأول للاتزان الانتقالي والثاني للدوراني. في الألواح اجعل مجموع العزوم المؤثرة في اتجاه الساعة يساوي عكسها."],
["حفظ الزخم الزاوي","L = Iω = ثابت","إذا انعدم العزم الخارجي بقي L ثابتًا، فإذا قلّ I زادت ω والعكس."],
["قانون نيوتن الثاني للدوران","Στ = Iα","عزم القصور الذاتي I هو مقاومة الجسم لتغيير حركته الدورانية، ويعتمد على توزيع الكتلة حول المحور."],
["الزخم","p = m v","كمية متجهة وحدتها kg·m/s، واتجاهه اتجاه السرعة."],
["الدفع والزخم","J = FΔt = Δp","الدفع يساوي التغير في الزخم. زيادة زمن التصادم تقلل القوة المتوسطة لنفس الدفع."],
["حفظ الزخم","Σp قبل = Σp بعد","يتحقق في نظام معزول (محصلة القوى الخارجية صفر أو مهملة). اكتب زخم كل جسم قبل وبعد وراعِ الإشارات."],
["التصادم غير المرن تمامًا","m₁v₁ + m₂v₂ = (m₁+m₂)v′","يلتحم الجسمان ويتحركان بسرعة مشتركة. الزخم محفوظ، أما جزء من الطاقة الحركية فيتحول إلى أشكال أخرى."],
["الشغل","W = F d cosθ","θ هي الزاوية بين القوة والإزاحة: 0° شغل موجب، 90° صفر، 180° سالب."],
["القدرة","P = W / t = F v","القدرة معدل إنجاز الشغل، ووحدتها الواط W = J/s."],
["الكفاءة","η = (W الناتج / W المبذول) × 100%","الآلة الحقيقية كفاءتها أقل من 100% بسبب الاحتكاك وفقد الطاقة حرارةً."],
["الطاقة الحركية","K = ½ m v²","تتناسب مع مربع السرعة: ضاعف السرعة تصبح الطاقة أربعة أمثال."],
["طاقة وضع الجاذبية","Ug = m g h","تتناسب طرديًا مع الكتلة والارتفاع عن مستوى الصفر الذي تختاره."],
["حفظ الطاقة الميكانيكية","K₁ + U₁ = K₂ + U₂","عند إهمال الاحتكاك ومقاومة الهواء تتحول طاقة الوضع إلى حركية ويبقى المجموع ثابتًا."],
["الحرارة المنتقلة","Q = m c ΔT","تعتمد على الكتلة والحرارة النوعية والتغير في درجة الحرارة ΔT = النهائية − الابتدائية."],
["الحرارة الكامنة","Q = m L","تُستخدم أثناء تغير الحالة، وتبقى درجة الحرارة ثابتة لأن الطاقة تُستهلك في تغيير الحالة."],
["القانون الأول للديناميكا الحرارية","ΔU = Q − W","Q الحرارة الداخلة، وW الشغل الذي يبذله النظام (حسب الاصطلاح المستخدم هنا)."],
["التحويل إلى كلفن","T(K) = T(°C) + 273","للتحويل العكسي اطرح 273."],
["الاتزان الحراري","T₁ = T₂","تنتقل الحرارة من الأعلى درجة إلى الأقل حتى تتساوى الدرجتان ويتوقف الانتقال الصافي."],
["طرق انتقال الحرارة","توصيل · حمل · إشعاع","الإشعاع ينتقل عبر الفراغ ولا يحتاج وسطًا مادّيًا."],
["الكميات المتجهة","مقدار + اتجاه","الزخم والقوة والسرعة متجهات، أما الشغل والطاقة والقدرة فكميات قياسية."],
["التسارع المركزي","aᶜ = v² / r = rω²","يتجه نحو مركز المسار، ويتناسب مع مربع السرعة عند ثبات r."],
["الطاقة المرونية","Uₑ = ½ k x²","الزنبرك المضغوط أو الممدود يخزن طاقة وضع مرونية."],
["الآلة المثالية","W المبذول = W الناتج","لا يوجد فقد للطاقة، وكفاءتها 100%."],
["الفائدة الميكانيكية للرافعة","IMA = ذراع الجهد ÷ ذراع المقاومة","كلما طال ذراع الجهد قلّت القوة اللازمة."]];
const QL=[0,9,13,6,16,23,13,11,0,0,3,5,6,9,10,11,13,14,15,16,16,17,18,19,19,20,22,21,26,8,7,13,25,28,0,1,0,2,3,5,3,6,7,4,9,12,10,10,12,13,13,14,29,15,18,18,27,17,19,23,21,22,20,24];
const lawBox=i=>{const l=LW[QL[i]];return l?`<b>${l[0]}</b><div class="formula">${l[1]}</div><p class="muted">${l[2]}</p>`:''};
function showLaw(i){const b=document.getElementById('lw'+i);b.innerHTML=lawBox(i);b.classList.toggle('hide')}


renderQuiz();applyQF();updateQuizProgress();

