// ===== كيف أتعامل مع القانون =====
const HW=[
{t:"الجذب الكوني",p:"تتجاذب كتلتان بقوة 40 N. ما قوة التجاذب إذا تضاعفت المسافة بينهما وبقيت الكتلتان ثابتتين؟",g:["F₁ = 40 N","r₂ = 2 r₁"],u:"F₂",law:"F = G m₁m₂ / r²",why:"المسألة مقارنة بين حالتين، فلا نحتاج G ولا الكتل؛ نستخدم النسبة F ∝ 1/r².",conv:"",sub:"F₂ = F₁ × (r₁/r₂)² = 40 × (1/2)²",ans:10,unit:"N",check:"زادت المسافة فلا بد أن تقل القوة؛ 10 N أقل من 40 N فالنتيجة معقولة."},
{t:"الزخم",p:"جسم كتلته 2 kg يتحرك بسرعة 36 km/h. ما زخمه؟",g:["m = 2 kg","v = 36 km/h"],u:"p",law:"p = m v",why:"المعطيات كتلة وسرعة والمطلوب كمية الحركة، وهذا تعريف الزخم.",conv:"36 km/h = 36 ÷ 3.6 = 10 m/s",sub:"p = 2 × 10",ans:20,unit:"kg·m/s",check:"الوحدة kg·m/s تطابق وحدة الزخم، واتجاهه اتجاه السرعة."},
{t:"الشغل",p:"تؤثر قوة 20 N بزاوية 60° مع الأفقي في جسم فتحركه 300 cm أفقيًا. ما الشغل؟",g:["F = 20 N","θ = 60°","d = 300 cm"],u:"W",law:"W = F d cosθ",why:"قوة وإزاحة وزاوية بينهما والمطلوب الشغل، فنستخدم قانون الشغل مع cosθ.",conv:"300 cm = 3 m (قسمة على 100)",sub:"W = 20 × 3 × cos 60° = 20 × 3 × 0.5",ans:30,unit:"J",check:"الزاوية أقل من 90° فالشغل موجب، وأقل من F·d = 60 J."},
{t:"عزم القوة",p:"مفتاح ربط طوله 40 cm، أثرت قوة 50 N في طرفه بزاوية 30° مع المفتاح. ما عزم القوة؟",g:["r = 40 cm","F = 50 N","θ = 30°"],u:"τ",law:"τ = r F sinθ",why:"قوة تدير جسمًا حول محور وبينها وبين الذراع زاوية، فنستخدم قانون العزم.",conv:"40 cm = 0.4 m",sub:"τ = 0.4 × 50 × sin 30° = 0.4 × 50 × 0.5",ans:10,unit:"N·m",check:"sin 30° = 0.5 فالعزم نصف أكبر قيمة ممكنة (20 N·m)."},
{t:"الطاقة الحركية",p:"سيارة كتلتها 1000 kg تسير بسرعة 72 km/h. ما طاقتها الحركية؟",g:["m = 1000 kg","v = 72 km/h"],u:"K",law:"K = ½ m v²",why:"كتلة وسرعة والمطلوب طاقة الحركة.",conv:"72 km/h = 72 ÷ 3.6 = 20 m/s",sub:"K = ½ × 1000 × 20² = ½ × 1000 × 400",ans:200000,unit:"J",check:"ربّع السرعة قبل الضرب؛ نسيان التربيع يعطي ناتجًا أقل بـ 20 مرة."},
{t:"حفظ الطاقة",p:"أُفلتت كرة كتلتها 0.5 kg من ارتفاع 5 m. ما سرعتها لحظة وصولها الأرض؟ (g = 10 m/s²، أهمل مقاومة الهواء)",g:["m = 0.5 kg","h = 5 m","g = 10 m/s²"],u:"v",law:"mgh = ½ m v²  ⟹  v = √(2gh)",why:"الطاقة محفوظة: Ug في الأعلى تتحول كلها إلى K عند الأرض، والكتلة تُحذف من الطرفين.",conv:"",sub:"v = √(2 × 10 × 5) = √100",ans:10,unit:"m/s",check:"السرعة لا تعتمد على الكتلة، و10 m/s معقولة لسقوط 5 m."},
{t:"الحرارة",p:"سُخّن 400 g من الماء من 20°C إلى 45°C. احسب الحرارة اللازمة (c = 4180 J/kg·°C).",g:["m = 400 g","T₁ = 20°C ، T₂ = 45°C","c = 4180 J/kg·°C"],u:"Q",law:"Q = m c ΔT",why:"ارتفاع درجة الحرارة دون تغير حالة، فنستخدم mcΔT وليس mL.",conv:"400 g = 0.4 kg ، ΔT = 45 − 20 = 25°C",sub:"Q = 0.4 × 4180 × 25",ans:41800,unit:"J",check:"Q موجبة لأن الماء امتص حرارة وارتفعت حرارته."},
{t:"حفظ الزخم",p:"عربة 3 kg تتحرك بسرعة 4 m/s اصطدمت بعربة ساكنة كتلتها 1 kg والتحمتا. ما سرعتهما معًا؟",g:["m₁ = 3 kg ، v₁ = 4 m/s","m₂ = 1 kg ، v₂ = 0"],u:"v′",law:"m₁v₁ + m₂v₂ = (m₁ + m₂) v′",why:"نظام معزول، فالزخم قبل = الزخم بعد، والتحام الجسمين يعني سرعة مشتركة.",conv:"",sub:"3×4 + 1×0 = (3+1) v′  ⟹  v′ = 12 ÷ 4",ans:3,unit:"m/s",check:"السرعة أقل من 4 m/s لأن الكتلة المتحركة زادت، وهذا منطقي."}];
let hi=0,hs=0,hr=false;const fmt=n=>n.toLocaleString('en');
const HWT=['اقرأ المسألة','اكتب المعطيات والمطلوب','اختر القانون','وحّد الوحدات','عوّض بالأرقام','احسب','اكتب الوحدة وراجع المعقولية'];
function hwBody(k){const e=HW[hi];return[
`<p>${e.p}</p>`,
`<div class="chips">${e.g.map(x=>`<span class="chip on">${x}</span>`).join('')}<span class="chip">المطلوب: ${e.u}</span></div>`,
`<div class="formula">${e.law}</div><p class="muted">${e.why}</p>`,
`<p>${e.conv||'الوحدات كلها بالنظام الدولي فلا حاجة للتحويل.'}</p>`,
`<div class="formula">${e.sub}</div>`,
hr?`<div class="formula">${e.u} = ${fmt(e.ans)} ${e.unit}</div>`:`<p class="muted">احسبها بنفسك قبل أن ترى الحل:</p><div class="hwin"><input id="hw_in" type="number" step="any" inputmode="decimal" placeholder="الناتج"><button class="btn" onclick="hwCheck()">تحقق</button><button class="btn" onclick="hwReveal()">اعرض الحل</button></div><div id="hw_res" class="feedback"></div>`,
`<p><b>${fmt(e.ans)} ${e.unit}</b></p><p class="muted">${e.check}</p>`][k]}
function hwRender(){let h='';for(let k=0;k<=hs;k++)h+=`<div class="hw-step ${k===hs?'cur':''}"><span class="num">${(k+1).toLocaleString('ar-SA')}</span><div><b>${HWT[k]}</b>${hwBody(k)}</div></div>`;
document.getElementById('hwSteps').innerHTML=h;document.getElementById('hwBar').style.width=((hs+1)/7*100)+'%';
document.getElementById('hwNext').textContent=hs===6?'مسألة أخرى ←':'الخطوة التالية ←';
const c=document.querySelector('.hw-step.cur');c&&c.scrollIntoView&&c.scrollIntoView({behavior:'smooth',block:'nearest'})}
function hwLoad(i){hi=i;hs=0;hr=false;window.speechSynthesis&&speechSynthesis.cancel();document.getElementById('hwChips').innerHTML=HW.map((q,j)=>`<button class="chip ${j===i?'on':''}" onclick="hwLoad(${j})">${q.t}</button>`).join('');hwRender()}
function hwStep(d){if(d>0&&hs===5)hr=true;if(d>0&&hs===6){hwLoad((hi+1)%HW.length);return}hs=Math.max(0,Math.min(6,hs+d));hwRender()}
function hwReveal(){hr=true;hwRender()}
function hwCheck(){const v=parseFloat(document.getElementById('hw_in').value),a=HW[hi].ans,r=document.getElementById('hw_res');r.textContent=isNaN(v)?'اكتب رقمًا أولًا.':Math.abs(v-a)/a<.02?'✓ إجابة صحيحة! اضغط «الخطوة التالية».':'ليست صحيحة بعد: راجع التعويض والوحدات في الخطوات السابقة وحاول مرة ثانية.'}
function hwSpeak(){if(!window.speechSynthesis)return;const c=document.querySelector('.hw-step.cur');const u=new SpeechSynthesisUtterance(c.textContent);u.lang='ar-SA';speechSynthesis.cancel();speechSynthesis.speak(u)}
hwLoad(0);

