/* مرفوعة من هذا القسم لتحافظ على ترتيب التنفيذ الأصلي */
answer=function answer(i,j,el){if(answered.has(i))return;answered.add(i);const q=questions[i],p=document.getElementById('q'+i);p.querySelectorAll('.option').forEach((b,k)=>{b.disabled=true;if(k===q.a)b.classList.add('correct')});const ok=j===q.a;if(ok){score++;document.getElementById('f'+i).textContent="إجابة صحيحة! "+q.e}else{el.classList.add('wrong');document.getElementById('f'+i).textContent="ليست الإجابة الصحيحة. "+q.e}const b=document.getElementById('lw'+i);b.innerHTML=lawBox(i);b.classList.remove('hide');document.getElementById('scoreStat').textContent=score.toLocaleString('ar-SA');updateQuizProgress();PS.ans[i]=ok?1:0;pAdd(ok?10:2)};
// ===== النسخة الجبارة =====
const PS=Object.assign({xp:0,streak:0,last:'',ans:{},best:0,fc:{}},(()=>{try{return JSON.parse(localStorage.getItem('phy2_v1'))||{}}catch(e){return{}}})());
const pSave=()=>{try{localStorage.setItem('phy2_v1',JSON.stringify(PS))}catch(e){}};
const TT=["مبتدئ","متعلّم","محلّل","مختبِر","فيزيائي","جاليليو","نيوتن","أينشتاين"],pLvl=x=>1+Math.floor(Math.sqrt(x/40)),ar=n=>(+n).toLocaleString('ar-SA'),ttl=l=>TT[Math.min(l-1,TT.length-1)];
function toast(m){const t=document.getElementById('toast');t.textContent=m;t.classList.add('show');clearTimeout(toast.k);toast.k=setTimeout(()=>t.classList.remove('show'),2800)}
function pTouch(){const d=new Date(),k=d.toISOString().slice(0,10);if(PS.last===k)return;PS.streak=PS.last===new Date(d-864e5).toISOString().slice(0,10)?PS.streak+1:1;PS.last=k}
function pAdd(n){const a=pLvl(PS.xp);PS.xp+=n;pTouch();const b=pLvl(PS.xp);if(b>a)toast(`🎉 ترقّيت إلى المستوى ${ar(b)}: ${ttl(b)}`);pSave();pRender()}
function pStats(){const o=[];for(let c=1;c<=6;c++){const ids=questions.map((q,i)=>i).filter(i=>questions[i].ch===c),d=ids.filter(i=>i in PS.ans);o.push({c,tot:ids.length,d:d.length,r:d.filter(i=>PS.ans[i]).length})}return o}
function pRender(){const l=pLvl(PS.xp),lo=40*(l-1)**2,up=40*l*l,st=pStats(),D=st.reduce((a,x)=>a+x.d,0),R=st.reduce((a,x)=>a+x.r,0),$=id=>document.getElementById(id);
$('plLvl').textContent=ar(l);$('plTitle').textContent=ttl(l);$('plXp').textContent=`${ar(PS.xp)} / ${ar(up)} XP`;$('plStreak').textContent=`🔥 ${ar(PS.streak)} يوم`;$('plBar').style.width=((PS.xp-lo)/(up-lo)*100)+'%';$('plAcc').textContent=(D?ar(Math.round(R/D*100)):'٠')+'٪';
const weak=st.filter(x=>x.d>=2&&x.r/x.d<.7).sort((a,b)=>a.r/a.d-b.r/b.d)[0],fresh=st.find(x=>x.d===0);
$('progBody').innerHTML=`<div class="grid2"><div class="mini"><h4>المستوى</h4><p>${ar(l)} · ${ttl(l)}</p></div><div class="mini"><h4>أيام متتالية</h4><p>🔥 ${ar(PS.streak)}</p></div><div class="mini"><h4>أفضل نتيجة في الاختبار النهائي</h4><p>${ar(PS.best)}٪</p></div><div class="mini"><h4>دقة الإجابات</h4><p>${D?ar(Math.round(R/D*100)):'٠'}٪ (${ar(R)} من ${ar(D)})</p></div></div><h3>إتقان الفصول</h3>${st.map(x=>`<div class="mini" style="margin:8px 0"><h4>الفصل ${ar(x.c)} · ${chapters[x.c-1].title}</h4><div class="progress-track"><div class="progress-fill" style="width:${x.r/x.tot*100}%"></div></div><p class="muted">${ar(x.r)} صحيحة من ${ar(x.tot)} · أجبت على ${ar(x.d)}</p></div>`).join('')}<div class="info">${weak?`أضعف فصولك الآن: <b>الفصل ${ar(weak.c)} · ${chapters[weak.c-1].title}</b>. <button class="btn" onclick="pGo(${weak.c})">تدرّب عليه</button>`:fresh?`ابدأ بالفصل ${ar(fresh.c)}، فلم تجب على أي سؤال منه بعد. <button class="btn" onclick="pGo(${fresh.c})">ابدأ</button>`:'أداؤك ممتاز في كل الفصول! جرّب الاختبار النهائي.'}</div><button class="btn" onclick="pReset()">مسح تقدمي</button>`}
function pGo(c){showSection('quiz');setTimeout(()=>{const b=document.querySelectorAll('#quiz .chips .chip')[c];b&&b.click()},60)}
function pReset(){if(!confirm('تمسح كل تقدمك؟'))return;Object.assign(PS,{xp:0,streak:0,last:'',ans:{},best:0,fc:{}});pSave();pRender();fcI>=0&&fcRender()}

// ===== الاختبار النهائي =====
let EX=null;const exFmt=t=>String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');
function exStart(){const ids=questions.map((q,i)=>i).sort(()=>Math.random()-.5).slice(0,15);EX={ids,i:0,a:[],t:900,id:setInterval(()=>{EX.t--;const e=document.getElementById('exT');e&&(e.textContent=exFmt(EX.t));EX.t<=0&&exFinish()},1000)};exRender()}
